mapper.sql:
where (#{status} = '' or o.status = #{status})
  and (#{traceId} = '' or  = #{traceId})
  and (
    #{search} = ''
    or cast(o.id as text) ilike #{searchPattern}
    or coalesce(o.idempotency_key, '') ilike #{searchPattern}
    or coalesce(o.last_error, '') ilike #{searchPattern}
    or  ilike #{searchPattern}
    or coalesce(o.event_payload_json ->> 'action', o.event_payload_json #>> '{record,action}', '') ilike #{searchPattern}
    or coalesce(o.event_payload_json ->> 'resourceType', o.event_payload_json ->> 'resource_type', o.event_payload_json #>> '{record,resourceType}', '') ilike #{searchPattern}
    or coalesce(o.event_payload_json ->> 'resourceId', o.event_payload_json ->> 'resource_id', o.event_payload_json #>> '{record,resourceId}', '') ilike #{searchPattern}
  )

mapper.select:
select code from rbac_permission where status = 'ENABLED' and code in
#{permissionCode}
order by code asc

mapper.insert:
insert into rbac_role (
    id, code, name, scope_type, is_system, is_builtin, status, description, created_by, updated_by
)
values (
    #{roleId}, #{code}, #{name}, #{scopeType}, false, false, 'ENABLED', #{description}, #{actorId}, #{actorId}
)

insert into rbac_role_permission (role_id, permission_id, effect, created_by) select #{roleId}, p.id, 'ALLOW', #{actorId} from rbac_permission p where p.status = 'ENABLED' and p.code in
#{permissionCode}
on conflict (role_id, permission_id) where deleted_at is null do nothing

insert into base_project (
    id, code, name, status, sensitivity_level, allow_public_model, created_by, updated_by
)
values (
    #{projectId}, #{code}, #{name}, 'PREPARING', #{sensitivityLevel}, #{allowPublicModel}, #{actorId}, #{actorId}
)

insert into base_application (
    id, project_id, code, name, app_type, default_web_url, default_api_base_url,
    sensitivity_level, allow_public_model, status, created_by, updated_by
)
values (
    #{appId}, #{projectId}, #{code}, #{name}, #{appType}, #{defaultWebUrl}, #{defaultApiBaseUrl},
    #{sensitivityLevel}, #{allowPublicModel}, 'ENABLED', #{actorId}, #{actorId}
)

insert into base_environment (
    id, project_id, app_id, scope_type, code, name, env_type, web_url, api_base_url, status, created_by, updated_by
)
values (
    #{envId}, #{projectId}, #{appId}, #{scopeType}, #{code}, #{name}, #{envType},
    #{webUrl}, #{endpoint}, 'ENABLED', #{actorId}, #{actorId}
)

mapper.select:
select count(*)
from base_config
where deleted_at is null
  and scope_type = 'SYSTEM'
  and config_key like 'integration.%'
  and (#{search} = ''
    or config_key ilike #{searchPattern}
    or coalesce(value_json ->> 'name', '') ilike #{searchPattern}
    or coalesce(value_json ->> 'category', '') ilike #{searchPattern}
    or coalesce(value_json ->> 'scope', '') ilike #{searchPattern})

select count(*)
from secret_reference sr
join secret_provider sp on sp.id = sr.provider_id and sp.deleted_at is null
where sr.deleted_at is null
  and (#{search} = ''
    or sr.secret_ref ilike #{searchPattern}
    or sr.purpose ilike #{searchPattern}
    or sr.scope_type ilike #{searchPattern}
    or sp.provider_code ilike #{searchPattern})

mapper.insert:
insert into base_config (
    scope_type, scope_id, config_key, value_kind, value_json, status, created_by, updated_by
)
values (
    #{scopeType}, null, #{configKey}, 'PLAIN', cast(#{valueJson} as jsonb), 'ENABLED', #{actorId}, #{actorId}
)

insert into secret_reference (
    id, provider_id, secret_ref, scope_type, scope_id, purpose, masked_value,
    secret_version, status, rotated_at, expires_at, created_by, updated_by
)
values (
    #{secretRefId}, #{providerId}, #{secretRef}, #{scopeType}, #{scopeId}, #{purpose}, #{maskedValue},
    #{secretVersion}, 'ACTIVE', now(), cast(#{expiresAt} as timestamptz), #{actorId}, #{actorId}
)

insert into secret_local_store (
    secret_ref_id, cipher_text, iv, auth_tag, algorithm, master_key_version, status, created_by, updated_by
)
values (
    #{secretRefId}, #{cipherText}, #{iv}, #{authTag}, #{algorithm}, #{masterKeyVersion}, 'ACTIVE', #{actorId}, #{actorId}
)

insert into rbac_role_binding (
    subject_type, subject_id, role_id, role_code, scope_type, scope_id, status, created_by, updated_by
)
values (
    'USER', #{userId}, #{roleId}, #{roleCode}, #{scopeType}, #{scopeId}, 'ENABLED', #{actorId}, #{actorId}
)
on conflict do nothing
